import {analyze,VERSION} from './core.mjs';
const overlap=(a,b)=>{const x=new Set(a),y=new Set(b),intersection=[...x].filter(v=>y.has(v)).length;return intersection/(x.size+y.size-intersection||1);};
export function challenge(dataset,settings={}){
  if(dataset?.samples?.length>50000)throw Error('Challenge suite supports at most 50,000 samples per run');
  const nominal=analyze(dataset,settings),o=nominal.settings;
  const cases=[{id:'nominal',settings:o},{id:'threshold-lower',settings:{...o,z_threshold:Math.max(1,o.z_threshold-.5)}},{id:'threshold-higher',settings:{...o,z_threshold:Math.min(10,o.z_threshold+.5)}},{id:'quorum-stricter',settings:{...o,quorum:Math.min(1,o.quorum+.15)}},{id:'grid-half-x',settings:o,shift:[o.cell_m/2,0]},{id:'grid-half-y',settings:o,shift:[0,o.cell_m/2]},{id:'grid-half-xy',settings:o,shift:[o.cell_m/2,o.cell_m/2]},{id:'cells-smaller',settings:{...o,cell_m:Math.max(5,o.cell_m*.75)}},{id:'cells-larger',settings:{...o,cell_m:Math.min(1000,o.cell_m*1.25)}}];
  const trials=cases.map(c=>{try{const d=c.shift?{...dataset,samples:dataset.samples.map(r=>({...r,x_m:r.x_m+c.shift[0],y_m:r.y_m+c.shift[1]}))}:dataset;return {...c,report:c.id==='nominal'?nominal:analyze(d,c.settings)};}catch(e){return {...c,error:e.message};}});
  const candidates=nominal.windows.filter(w=>w.detected).map(w=>{const voters=w.peers.filter(p=>p.eligible&&p.z>=o.z_threshold).map(p=>p.device);const checks=trials.map(c=>({id:c.id,status:c.error?'unsupported':c.report.windows.some(v=>v.detected&&v.start_s===w.start_s&&overlap(v.peers.filter(p=>p.eligible&&p.z>=c.report.settings.z_threshold).map(p=>p.device),voters)>=.5)?'supported':'not-supported'}));return {start_s:w.start_s,end_s:w.end_s,cell:w.cell,voters,checks,supported:checks.filter(c=>c.status==='supported').length,total:checks.length,classification:checks.every(c=>c.status==='supported')?'stable-under-tested-changes':'sensitive-to-analysis-choices'};});
  return {schema:'canopy-challenge/1',engine:VERSION,settings:o,trials:trials.map(c=>({id:c.id,settings:c.settings,shift:c.shift??[0,0],error:c.error??null,shared_windows:c.report?.summary.shared_windows??null})),candidates,summary:{nominal_candidates:candidates.length,stable_candidates:candidates.filter(c=>c.classification==='stable-under-tested-changes').length},limits:['Nine prespecified one-at-a-time perturbations, not a complete sensitivity proof or confidence probability.','Matching uses the same time window and voter-set Jaccard overlap >= 0.5; spatial coordinates alone are not matched.','No nominal finding means no candidate robustness conclusion. Correlated drift can remain stable.']};
}
